using FamilyVeda.Application.Common;
using FamilyVeda.Domain.Clinical;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Domain.Portal;
using FamilyVeda.Infrastructure.Persistence;
using FamilyVeda.Infrastructure.Portal;
using FluentAssertions;
using Microsoft.EntityFrameworkCore;

namespace FamilyVeda.UnitTests;

public sealed class PortalDashboardAndNotificationTests
{
    private static AppDbContext NewDb() =>
        new(new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);

    [Fact]
    public async Task FamilyDashboard_ForHead_DoesNotCountAdultMembersAppointmentsOrCases()
    {
        await using var db = NewDb();
        var head = new UserAccount { Email = "head@example.invalid", PasswordHash = "x", DisplayName = "Head", UserType = UserType.FamilyUser };
        var family = new Family { Name = "F", CreatedByUser = head, FamilyCode = "FV-DDD444" };
        var headMember = new Member { Family = family, User = head, DisplayName = "Head", DateOfBirth = new DateOnly(1980, 1, 1), Role = FamilyRole.Head };
        var adultUser = new UserAccount { Email = "adult@example.invalid", PasswordHash = "x", DisplayName = "Adult", UserType = UserType.FamilyUser };
        var adultMember = new Member { Family = family, User = adultUser, DisplayName = "Adult", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.AdultMember };
        var doctorUser = new UserAccount { Email = "doc@example.invalid", PasswordHash = "x", DisplayName = "Doc", UserType = UserType.Doctor };
        var doctor = new FamilyVeda.Domain.Clinical.Doctor { User = doctorUser, RegistrationNumberHash = "h", RegistrationNumberLastFour = "1234", VerificationStatus = VerificationStatus.Verified };
        var assignment = new FamilyDoctorAssignment { Family = family, Doctor = doctor, IsPrimary = true };
        db.AddRange(head, family, headMember, adultUser, adultMember, doctorUser, doctor, assignment);
        await db.SaveChangesAsync();

        var adultAppointment = new Appointment { Member = adultMember, Doctor = doctor, BookedByUserId = adultUser.Id, StartsAt = DateTimeOffset.UtcNow.AddDays(1), DurationMinutes = 30, Reason = "Private" };
        db.Add(adultAppointment);
        await db.SaveChangesAsync();

        var service = new PortalDashboardService(db, new StubCurrentUser(head.Id));
        var dashboard = await service.GetFamilyDashboardAsync(CancellationToken.None);

        dashboard.NextAppointment.Should().BeNull();
    }

    [Fact]
    public async Task Notifications_OnlyReturnOwn()
    {
        await using var db = NewDb();
        var userA = new UserAccount { Email = "a@example.invalid", PasswordHash = "x", DisplayName = "A", UserType = UserType.FamilyUser };
        var userB = new UserAccount { Email = "b@example.invalid", PasswordHash = "x", DisplayName = "B", UserType = UserType.FamilyUser };
        db.AddRange(userA, userB);
        db.Add(new PortalNotification { UserId = userA.Id, Type = "TEST", Title = "For A", Body = "Body" });
        db.Add(new PortalNotification { UserId = userB.Id, Type = "TEST", Title = "For B", Body = "Body" });
        await db.SaveChangesAsync();

        var service = new PortalNotificationService(db, new StubCurrentUser(userA.Id));
        var mine = await service.GetMineAsync(false, CancellationToken.None);

        mine.Should().ContainSingle();
        mine.Single().Title.Should().Be("For A");
    }

    private sealed class StubCurrentUser(Guid userId) : ICurrentUser
    {
        public bool IsAuthenticated => true;
        public Guid UserId => userId;
        public UserType UserType => UserType.FamilyUser;
    }
}
